-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.deck_activations (
  user_id uuid default auth.uid() not null,
  deck_id text not null,
  active boolean not null,
  updated_at timestamp with time zone default now() not null,
  constraint deck_activations_pkey PRIMARY KEY (user_id, deck_id),
  constraint deck_activations_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint deck_activations_deck_id_check CHECK ((deck_id ~ '^[0-9]{1,20}$'::text))
);

CREATE TRIGGER quota_rows AFTER INSERT ON public.deck_activations FOR EACH ROW EXECUTE FUNCTION public.quota_rows('5000');

alter table public.deck_activations enable row level security;

create policy "own deck activations" on public.deck_activations
  as permissive
  for all
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)))
  with check (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant delete, insert, select, update on table public.deck_activations to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.deck_activations to service_role;
